typedef GuideText = ({String en, String fr});
typedef GuideSection = ({GuideText title, GuideText text, String? image});
typedef GuideChapter = ({String id, String icon, GuideText title, GuideText summary, List<GuideSection> sections});

const List<GuideChapter> guideChapters = [
  (
    id: "start",
    icon: "rocket",
    title: (en: "Get started in 15 minutes", fr: "Bien démarrer en 15 minutes"),
    summary: (en: "A guided exercise, step by step: build a real collection, write, find, calculate and share.", fr: "Un exercice guidé, pas à pas : construire une vraie collection, saisir, retrouver, calculer et partager."),
    sections: [
      (title: (en: "Before you start", fr: "Avant de commencer"), text: (en: "This training builds one real example from start to finish: **household expenses**. Do it once with your own figures; every other use of Brainy (stock, measurements, tasks, clients…) works the same way.\n\nThree words are enough:\n- a **collection** is the binder (here “Home”);\n- a **data format** is the model of a card (here “Expense”), with its fields;\n- an **entry** is one filled card (here “Market, 12,500 FCFA, 14 Nov.”).\n\nYou need an account (email or Google), about 15 minutes, and Brainy on the web, a computer or a phone: what you build on one appears on the others.", fr: "Cette formation construit un vrai exemple du début à la fin : les **dépenses de la maison**. Faites-la une fois avec vos propres chiffres ; tous les autres usages de Brainy (stock, mesures, tâches, clients…) fonctionnent de la même façon.\n\nTrois mots suffisent :\n- une **collection** est le classeur (ici « Maison ») ;\n- un **format de données** est le modèle d’une fiche (ici « Dépense »), avec ses champs ;\n- une **entrée** est une fiche remplie (ici « Marché, 12 500 FCFA, 14 nov. »).\n\nIl vous faut un compte (e-mail ou Google), environ 15 minutes, et Brainy sur le web, l’ordinateur ou le téléphone : ce que vous construisez sur l’un apparaît sur les autres."), image: null),
      (title: (en: "Step 1 — Create the collection (1 min)", fr: "Étape 1 — Créer la collection (1 min)"), text: (en: "1. Click **New collection** at the bottom of the side bar (on a phone, open the menu ☰ first).\n2. Choose **Start from scratch**. A ready template (Expenses, Tasks, Shop and stock…) would also work; here we build it ourselves to understand everything.\n3. Name it **Home** and confirm.\n\nThe collection opens with its header (number of entries and data formats) and three tabs: **Entries**, **Data formats**, **Tools**.", fr: "1. Cliquez sur **Nouvelle collection** en bas de la barre latérale (sur téléphone, ouvrez d’abord le menu ☰).\n2. Choisissez **Partir de zéro**. Un modèle prêt (Dépenses, Tâches, Commerce et stock…) conviendrait aussi ; ici nous le construisons nous-mêmes pour tout comprendre.\n3. Nommez-la **Maison** et validez.\n\nLa collection s’ouvre avec son en-tête (nombre d’entrées et de formats de données) et trois onglets : **Entrées**, **Formats de données**, **Outils**."), image: "templates"),
      (title: (en: "Step 2 — Design the data format (4 min)", fr: "Étape 2 — Concevoir le format de données (4 min)"), text: (en: "*Start from scratch* created one simple data format, **General**, with a **Title** field. Open the **Data formats** tab, then the **⋯** menu of its card → **Edit data format**. Rename it **Expense** (its pastel color changes with **⋯ → Change color**). Rename the field and add the others with **Add field**:\n1. **Label** — type *Title* (the existing field). Turn on **Required**: an expense without a label is refused.\n2. **Amount** — type *Number*, unit *FCFA* (or €, \$… or your own). Turn on **Required** and **Show in the list**.\n3. **Date** — type *Date*. Turn on **Show in the list**.\n4. **Category** — type *Single choice*, one choice per line: Groceries, Transport, Health, School, Leisure. Turn on **Show in the list**.\n5. **Paid by** — type *Collaborator* (useful later, when the family shares the collection).\n\nGood to know:\n- **Required** fields carry a * in the form; the others can stay empty.\n- **Show in the list** chooses the values seen on each row, three at most.\n- **Maximum number of entries** stays empty here (no limit). Set 1 for a unique card (a cover, a profile), 12 for one card per month…\n- Field order is changed with the arrows; a field that already holds values keeps its type and unit, so your data stays consistent.", fr: "*Partir de zéro* a créé un format de données simple, **Général**, avec un champ **Titre**. Ouvrez l’onglet **Formats de données**, puis le menu **⋯** de sa carte → **Modifier le format de données**. Renommez-le **Dépense** (sa couleur pastel se change avec **⋯ → Changer la couleur**). Renommez le champ et ajoutez les autres avec **Ajouter un champ** :\n1. **Libellé** — type *Titre* (le champ existant). Activez **Obligatoire** : une dépense sans libellé est refusée.\n2. **Montant** — type *Nombre*, unité *FCFA* (ou €, \$… ou la vôtre). Activez **Obligatoire** et **Afficher dans la liste**.\n3. **Date** — type *Date*. Activez **Afficher dans la liste**.\n4. **Catégorie** — type *Choix unique*, un choix par ligne : Courses, Transport, Santé, École, Loisirs. Activez **Afficher dans la liste**.\n5. **Payé par** — type *Collaborateur* (utile plus tard, quand la famille partagera la collection).\n\nÀ savoir :\n- Les champs **obligatoires** portent un * dans le formulaire ; les autres peuvent rester vides.\n- **Afficher dans la liste** choisit les valeurs visibles sur chaque ligne, trois au plus.\n- **Nombre maximal d’entrées** reste vide ici (sans limite). Mettez 1 pour une fiche unique (une couverture, un profil), 12 pour une fiche par mois…\n- L’ordre des champs se change avec les flèches ; un champ qui contient déjà des valeurs garde son type et son unité, pour que vos données restent cohérentes."), image: "format-editor"),
      (title: (en: "Step 3 — Write your first entries (3 min)", fr: "Étape 3 — Saisir vos premières entrées (3 min)"), text: (en: "1. Click **New entry**. The form shows the fields of **Expense**; those marked * are required.\n2. Type *Market*, *12500*, today’s date, *Groceries*, then **Save entry**. The decimal comma is accepted (12,5) and the unit is added for you.\n3. For the next ones, use **Quick entry** (Entries tab): it remembers your usual values and the “today” dates, and can duplicate the last entry. Add five or six expenses in different categories.\n\nNo network? The entry is kept on the device and sent as soon as the connection is back (attachments excepted).", fr: "1. Cliquez sur **Nouvelle entrée**. Le formulaire présente les champs de **Dépense** ; ceux marqués * sont obligatoires.\n2. Tapez *Marché*, *12500*, la date du jour, *Courses*, puis **Enregistrer l’entrée**. La virgule décimale est acceptée (12,5) et l’unité est ajoutée pour vous.\n3. Pour les suivantes, utilisez la **Saisie rapide** (onglet Entrées) : elle retient vos valeurs habituelles et les dates « aujourd’hui », et peut dupliquer la dernière entrée. Ajoutez cinq ou six dépenses de catégories différentes.\n\nPas de réseau ? L’entrée est gardée sur l’appareil et envoyée dès que la connexion revient (sauf les pièces jointes)."), image: "entry-form"),
      (title: (en: "Step 4 — Read and find (2 min)", fr: "Étape 4 — Lire et retrouver (2 min)"), text: (en: "Each entry is one slim row in its pastel color: the label, the three values you chose, the data format and the creation date (and the change date after an edit).\n- **Double-click** a row (double-tap on a phone), or click its title or 👁 **Details**, to see every value. The **⋯** menu edits, copies as readable text, links to other entries, sets a reminder or deletes.\n- Press **/** to jump into the search, then type a word or a value: *market*.\n- Filter by **data format** and by **field**: *Category equals Groceries*, *Amount greater than 10000*. **Clear filters** brings everything back.\n- With many entries, the bar above the list gives the total, the first and last pages, a **page number** to type, **Go to date** and **Per page** (30, 50 or 100). Thousands of entries stay a few clicks away.", fr: "Chaque entrée est une ligne fine à sa couleur pastel : le libellé, les trois valeurs choisies, le format de données et la date de création (et la date de modification après un changement).\n- **Double-cliquez** une ligne (double-toucher sur téléphone), ou cliquez son titre ou 👁 **Détails**, pour voir toutes les valeurs. Le menu **⋯** modifie, copie en texte lisible, relie à d’autres entrées, programme un rappel ou supprime.\n- Appuyez sur **/** pour aller dans la recherche, puis tapez un mot ou une valeur : *marché*.\n- Filtrez par **format de données** et par **champ** : *Catégorie égale Courses*, *Montant supérieur à 10000*. **Effacer les filtres** remet tout.\n- Avec beaucoup d’entrées, la barre au-dessus de la liste donne le total, la première et la dernière page, un **numéro de page** à taper, **Aller à la date** et **Par page** (30, 50 ou 100). Des milliers d’entrées restent à quelques clics."), image: "collection"),
      (title: (en: "Step 5 — Save a view (1 min)", fr: "Étape 5 — Enregistrer une vue (1 min)"), text: (en: "Keep the filter *Category equals Groceries*, click **Save a view** and name it **Groceries**. Choose its layout: list, table (with the spreadsheet mode), cards, tasks or calendar.\n\nThe **View** list now offers *Default list* and *Groceries*. Brainy remembers the collection and the view you last opened, on your account: close the app, open it on another device, and you find the same screen.", fr: "Gardez le filtre *Catégorie égale Courses*, cliquez sur **Enregistrer une vue** et nommez-la **Courses**. Choisissez sa présentation : liste, tableau (avec le mode tableur), fiches, tâches ou agenda.\n\nLa liste **Vue** propose maintenant *Liste par défaut* et *Courses*. Brainy retient la collection et la vue ouvertes en dernier, sur votre compte : fermez l’application, ouvrez-la sur un autre appareil, vous retrouvez le même écran."), image: "table"),
      (title: (en: "Step 6 — Calculate (2 min)", fr: "Étape 6 — Calculer (2 min)"), text: (en: "1. Click **Calculations** in the collection header.\n2. Choose **Expense**, the field **Amount** and the operation **Sum**.\n3. Group by **month**, then by **Category**: you see where the money goes, as a key figure or a chart (bars, lines, stacked areas…).\n\nUnits are kept (FCFA stays FCFA), and you can compare two periods or export the chart. No formula to write.", fr: "1. Cliquez sur **Calculs** dans l’en-tête de la collection.\n2. Choisissez **Dépense**, le champ **Montant** et l’opération **Somme**.\n3. Regroupez par **mois**, puis par **Catégorie** : vous voyez où va l’argent, en chiffre clé ou en graphique (barres, courbes, aires empilées…).\n\nLes unités sont conservées (les FCFA restent des FCFA), et vous pouvez comparer deux périodes ou exporter le graphique. Aucune formule à écrire."), image: "insights"),
      (title: (en: "Step 7 — Share with someone (2 min)", fr: "Étape 7 — Partager avec quelqu’un (2 min)"), text: (en: "1. In **More actions → Collaborators**, copy your personal link and send it (WhatsApp, email…). When the person accepts, you become collaborators; nothing is shared yet.\n2. In the collection, click **Share**, choose the person and **Read and write** (or **Read only**).\n3. The collection appears under **Shared with me** for them. Each row then shows who wrote it and who changed it last, and the **Paid by** field lets you say who paid.\n\nThe structure (data formats) stays yours; your collaborators only add and edit entries.", fr: "1. Dans **Autres actions → Collaborateurs**, copiez votre lien personnel et envoyez-le (WhatsApp, e-mail…). Quand la personne l’accepte, vous devenez collaborateurs ; rien n’est encore partagé.\n2. Dans la collection, cliquez sur **Partager**, choisissez la personne et **Lecture et écriture** (ou **Lecture seule**).\n3. La collection apparaît chez elle sous **Partagées avec moi**. Chaque ligne indique alors qui l’a écrite et qui l’a modifiée en dernier, et le champ **Payé par** dit qui a payé.\n\nLa structure (les formats de données) reste la vôtre ; vos collaborateurs ajoutent et modifient seulement les entrées."), image: "share"),
      (title: (en: "You are ready: checklist and next steps", fr: "Vous êtes prêt : bilan et suite"), text: (en: "You now know how to:\n- create a collection and design a data format with required fields, list fields and an entry limit;\n- write entries quickly, even offline;\n- find any entry with search, filters, pages and dates;\n- save views, calculate and share.\n\nNext steps, at your pace:\n- add a second data format to the same collection, for example **Income**, with another color;\n- try a ready template (Tasks with recurrences and reminders, Shop and stock, Measurements, Book);\n- read the chapter **What Brainy does for you** for ideas at home and at work.", fr: "Vous savez maintenant :\n- créer une collection et concevoir un format de données avec champs obligatoires, champs de liste et limite d’entrées ;\n- saisir vite, même hors connexion ;\n- retrouver n’importe quelle entrée par recherche, filtres, pages et dates ;\n- enregistrer des vues, calculer et partager.\n\nPour la suite, à votre rythme :\n- ajoutez un second format de données à la même collection, par exemple **Recette**, d’une autre couleur ;\n- essayez un modèle prêt (Tâches avec répétitions et rappels, Commerce et stock, Mesures, Livre) ;\n- lisez le chapitre **Ce que Brainy vous apporte** pour des idées à la maison et au travail."), image: null),
    ],
  ),
  (
    id: "benefits",
    icon: "briefcase",
    title: (en: "What Brainy does for you: at home and at work", fr: "Ce que Brainy vous apporte : à la maison et au travail"),
    summary: (en: "Concrete uses and gains for a household, a small business, and industry, farms or field teams.", fr: "Usages et gains concrets pour un foyer, une petite entreprise, et l’industrie, l’agriculture ou les équipes de terrain."),
    sections: [
      (title: (en: "Why Brainy rather than a notebook or a spreadsheet", fr: "Pourquoi Brainy plutôt qu’un cahier ou un tableur"), text: (en: "- **Your structure, not a fixed app**: you decide what to record, field by field, and change it as your needs grow.\n- **Clean data from the start**: field types, units, required fields and entry limits stop mistakes at the moment they are typed.\n- **Found in seconds**: search, filters, saved views, pages and dates, even with thousands of entries.\n- **Answers without formulas**: totals, averages, trends and charts by day, month, category, person or zone.\n- **Everywhere, even offline**: web, phone and computer show the same data, and entries typed without network are sent later.\n- **Private and shared on your terms**: nothing is public; you share one collection at a time, in read only or read and write, and sensitive fields can stay hidden.", fr: "- **Votre structure, pas une application figée** : vous décidez quoi noter, champ par champ, et la faites évoluer avec vos besoins.\n- **Des données propres dès le départ** : types de champs, unités, champs obligatoires et limites d’entrées arrêtent les erreurs au moment de la saisie.\n- **Retrouvé en quelques secondes** : recherche, filtres, vues enregistrées, pages et dates, même avec des milliers d’entrées.\n- **Des réponses sans formules** : totaux, moyennes, tendances et graphiques par jour, mois, catégorie, personne ou zone.\n- **Partout, même hors connexion** : web, téléphone et ordinateur montrent les mêmes données, et les saisies faites sans réseau sont envoyées plus tard.\n- **Privé, et partagé à vos conditions** : rien n’est public ; vous partagez une collection à la fois, en lecture seule ou en lecture et écriture, et les champs sensibles peuvent rester cachés."), image: null),
      (title: (en: "At home and for the family", fr: "À la maison et pour la famille"), text: (en: "- **Budget**: expenses and income with totals per week, month and year; see where the money goes and compare months.\n- **House and pantry**: what is in stock, what to buy, warranties and receipts kept as attachments.\n- **Chores and tasks**: once or repeating (every day, some weekdays, every month), checked day by day, with reminders; the family shares the list and each task says who did it.\n- **Health follow-up**: weight, blood pressure, sleep or treatments as dated measures with units, shown as curves to bring to the doctor.\n- **Children and school**: grades, homework, activities, vaccinations.\n- **Car and maintenance**: refuelling, services, repairs and costs per vehicle.\n- **Memories and interests**: recipes, saved links and videos with previews, books read, sport sessions, a diary or a whole book laid out as real pages.\n\n**What you gain**: one place instead of scattered papers, notes and messages; answers in seconds (“how much did we spend on transport in March?”); a family that sees the same thing.", fr: "- **Budget** : dépenses et recettes avec totaux par semaine, mois et année ; voir où va l’argent et comparer les mois.\n- **Maison et provisions** : ce qui est en stock, ce qu’il faut acheter, garanties et reçus gardés en pièces jointes.\n- **Tâches ménagères** : une fois ou en répétition (chaque jour, certains jours, chaque mois), cochées jour par jour, avec rappels ; la famille partage la liste et chaque tâche dit qui l’a faite.\n- **Suivi de santé** : poids, tension, sommeil ou traitements en mesures datées avec unités, affichés en courbes à montrer au médecin.\n- **Enfants et école** : notes, devoirs, activités, vaccins.\n- **Voiture et entretien** : pleins, révisions, réparations et coûts par véhicule.\n- **Souvenirs et passions** : recettes, liens et vidéos conservés avec aperçu, livres lus, séances de sport, un journal ou un livre entier mis en pages.\n\n**Ce que vous y gagnez** : un seul endroit au lieu de papiers, notes et messages dispersés ; des réponses en quelques secondes (« combien avons-nous dépensé en transport en mars ? ») ; une famille qui voit la même chose."), image: "tasks-day"),
      (title: (en: "For a shop, a craftsperson or a small business", fr: "Pour un commerce, un artisan ou une petite entreprise"), text: (en: "- **Sales and orders**: each sale is an entry; totals per day, month, product or seller come from **Calculations**.\n- **Stock**: receipts, sales, transfers between places and corrections become confirmed movements; the current stock is always computed, never typed by hand, and forecasts show what is coming.\n- **Clients and suppliers**: contacts, history and linked entries (a client and all its orders).\n- **Team work**: share a collection with employees in read and write; tasks have an assignee, states (to do → done → checked) and due dates; each row shows who wrote and changed it.\n- **Expenses and cash book**: amounts with units and currencies, exchange rates, period totals.\n- **Collect from outside**: a contribution link lets a client or partner send entries that wait in quarantine until you accept them.\n\n**What you gain**: fewer errors, a stock you can trust, figures ready for decisions, and a team working on the same up-to-date data without sending files around.", fr: "- **Ventes et commandes** : chaque vente est une entrée ; les totaux par jour, mois, produit ou vendeur viennent des **Calculs**.\n- **Stock** : réceptions, ventes, transferts entre lieux et corrections deviennent des mouvements confirmés ; le stock courant est toujours calculé, jamais tapé à la main, et les prévisions montrent ce qui arrive.\n- **Clients et fournisseurs** : contacts, historique et entrées liées (un client et toutes ses commandes).\n- **Travail en équipe** : partagez une collection avec vos employés en lecture et écriture ; les tâches ont un responsable, des états (à faire → fait → vérifié) et des échéances ; chaque ligne indique qui l’a écrite et modifiée.\n- **Dépenses et caisse** : montants avec unités et devises, taux de change, totaux par période.\n- **Collecter de l’extérieur** : un lien de contribution permet à un client ou un partenaire d’envoyer des entrées qui attendent en quarantaine jusqu’à votre accord.\n\n**Ce que vous y gagnez** : moins d’erreurs, un stock fiable, des chiffres prêts pour décider, et une équipe qui travaille sur les mêmes données à jour sans s’échanger de fichiers."), image: "tools"),
      (title: (en: "For industry, farms, laboratories and field teams", fr: "Pour l’industrie, l’agriculture, les laboratoires et les équipes de terrain"), text: (en: "- **Measurements you can rely on**: the *Measure* field records a value with its unit, uncertainty, quality and instrument; water, energy, temperature, production or quality-control readings stay comparable over time.\n- **Maintenance**: one object per machine with its characteristics and history; interventions, operating hours, spare parts in stock and repeating checks with reminders.\n- **Quality and traceability**: states and approvals per role (to review → validated), required fields before each step, an **append-only register** whose writings cannot be changed and are corrected by a linked counter-writing, an integrity proof and an **audit log** of who did what.\n- **Field and map**: positions and zones (parcels, sites, networks), distances and totals per zone, GeoJSON and CSV import and export.\n- **Shared references**: classifications and code lists (products, failures, species, diseases), hierarchical and versioned.\n- **Volume**: imports checked row by row against your data formats, background processing, large files stored by reference, and lists that stay fast with tens of thousands of entries.\n- **Confidentiality**: sensitivity levels per field, hidden from shares and exports unless you choose, and minimum group sizes in analyses.\n\n**What you gain**: data collected once, in the right unit, by the right person, at the right step; history and proof available on request; analyses and charts without exporting to another tool.\n\nBrainy helps you record, organize and prove; it does not by itself certify a legal, medical, tax or industrial compliance. Some heavy modules (large files, data sources, background processing, reminders) may be paused on a given hosting plan; Brainy says so when it happens.", fr: "- **Des mesures fiables** : le champ *Mesure* enregistre une valeur avec son unité, son incertitude, sa qualité et l’instrument ; les relevés d’eau, d’énergie, de température, de production ou de contrôle qualité restent comparables dans le temps.\n- **Maintenance** : un objet par machine avec ses caractéristiques et son historique ; interventions, heures de fonctionnement, pièces détachées en stock et contrôles répétés avec rappels.\n- **Qualité et traçabilité** : états et validations par rôle (à revoir → validé), champs obligatoires avant chaque étape, un **registre non modifiable** dont les écritures se corrigent par une contre-écriture liée, une preuve d’intégrité et un **journal d’audit** de qui a fait quoi.\n- **Terrain et carte** : positions et zones (parcelles, sites, réseaux), distances et totaux par zone, import et export GeoJSON et CSV.\n- **Références communes** : classifications et listes de codes (produits, pannes, espèces, maladies), hiérarchiques et versionnées.\n- **Volume** : imports vérifiés ligne par ligne contre vos formats de données, traitements en arrière-plan, gros fichiers conservés par référence, et des listes qui restent rapides avec des dizaines de milliers d’entrées.\n- **Confidentialité** : niveaux de sensibilité par champ, cachés des partages et des exports sauf choix contraire, et taille minimale des groupes dans les analyses.\n\n**Ce que vous y gagnez** : une donnée saisie une seule fois, dans la bonne unité, par la bonne personne, à la bonne étape ; l’historique et la preuve disponibles à la demande ; des analyses et des graphiques sans exporter vers un autre outil.\n\nBrainy vous aide à noter, organiser et prouver ; il ne certifie pas à lui seul une conformité légale, médicale, fiscale ou industrielle. Certains modules lourds (gros fichiers, sources de données, traitements en arrière-plan, rappels) peuvent être en pause sur un hébergement donné ; Brainy le signale quand c’est le cas."), image: "insights"),
      (title: (en: "Start small, grow without starting over", fr: "Commencer petit, grandir sans tout recommencer"), text: (en: "Everyone starts with one collection and one field. As needs grow, add fields, data formats, views, calculations, collaborators and advanced tools to the same collection: nothing has to be rebuilt, and entries already saved stay valid.\n\nA good method:\n1. Write down for a week what you note today on paper, in messages or in spreadsheets.\n2. Make one data format per kind of card, with only the fields you really use; mark as **Required** what must never be missing.\n3. Choose the three values to **show in the list**, save the views you open every day, then let **Calculations** answer your questions.", fr: "Chacun commence avec une collection et un champ. À mesure que les besoins grandissent, ajoutez à la même collection des champs, des formats de données, des vues, des calculs, des collaborateurs et des outils avancés : rien n’est à reconstruire, et les entrées déjà saisies restent valables.\n\nUne bonne méthode :\n1. Notez pendant une semaine ce que vous écrivez aujourd’hui sur papier, dans des messages ou dans des tableurs.\n2. Faites un format de données par type de fiche, avec seulement les champs que vous utilisez vraiment ; marquez **Obligatoire** ce qui ne doit jamais manquer.\n3. Choisissez les trois valeurs à **afficher dans la liste**, enregistrez les vues que vous ouvrez chaque jour, puis laissez les **Calculs** répondre à vos questions."), image: null),
    ],
  ),
  (
    id: "vision",
    icon: "compass",
    title: (en: "Brainy’s goal and vision", fr: "Objectif et vision de Brainy"),
    summary: (en: "Why Brainy exists, where it is going with large data, and how your privacy is kept.", fr: "Pourquoi Brainy existe, où il va avec les grandes données, et comment votre vie privée est protégée."),
    sections: [
      (title: (en: "Today: your structured notebook", fr: "Aujourd’hui : votre carnet structuré"), text: (en: "Brainy lets anyone write down, organize and find personal information on phone, computer and web. You decide the structure yourself: a collection, its data formats and their fields. A beginner starts with a single field; an expert adds units, formulas, objects and rules.\n\nEverything you save is typed: a date is a date, an amount keeps its unit, a checkbox is yes or no. That is what makes your notes calculable later.", fr: "Brainy permet à chacun de noter, organiser et retrouver ses informations sur téléphone, ordinateur et web. Vous choisissez vous-même la structure : une collection, ses formats de données et leurs champs. Un débutant commence avec un seul champ ; un expert ajoute unités, formules, objets et règles.\n\nTout ce que vous enregistrez est typé : une date est une date, un montant garde son unité, une case à cocher vaut oui ou non. C’est ce qui rend vos notes calculables ensuite."), image: "collection"),
      (title: (en: "Tomorrow: large data and studies", fr: "Demain : grandes données et études"), text: (en: "Brainy’s long-term goal is to handle data at industrial scale and to support scientific, mathematical and statistical studies on data of every type and from every field: health, farming, weather, trade, education, industry…\n\nThe foundations are already there:\n- typed fields, units and measures with uncertainty and quality;\n- calculations, statistics, charts and explainable forecasts;\n- objects, relations, classifications and maps;\n- large files stored by reference, background processing and connectors to outside sources;\n- an append-only register, audit and sensitivity levels.\n\nThe rest will arrive step by step. Brainy never promises legal, medical, tax or industrial compliance.", fr: "L’objectif à long terme de Brainy est de traiter des données à l’échelle industrielle et d’aider aux études scientifiques, mathématiques et statistiques sur des données de tous types et de tous domaines : santé, agriculture, météo, commerce, éducation, industrie…\n\nLes fondations existent déjà :\n- champs typés, unités et mesures avec incertitude et qualité ;\n- calculs, statistiques, graphiques et prévisions explicables ;\n- objets, relations, classifications et cartes ;\n- fichiers volumineux par référence, traitements en arrière-plan et connecteurs vers des sources externes ;\n- registre non modifiable, journal d’audit et niveaux de sensibilité.\n\nLe reste arrive peu à peu. Brainy ne promet aucune conformité légale, médicale, fiscale ou industrielle."), image: null),
      (title: (en: "Your data stays yours", fr: "Vos données restent les vôtres"), text: (en: "Collections and entries belong to your account and the server checks every access. Nothing is public:\n- private by default, only you see it;\n- shared only with your collaborators, collection by collection, in read only or read and write, and if you want only some fields;\n- public only if you decide to, for example by publishing a domain package (structure only, never your entries) or opening a contribution form.\n\nYour profile is private too. Connecting people is planned but not available yet, and it will always require your consent.", fr: "Les collections et les entrées appartiennent à votre compte et le serveur vérifie chaque accès. Rien n’est public :\n- privé par défaut, vous seul le voyez ;\n- partagé seulement avec vos collaborateurs, collection par collection, en lecture seule ou en lecture et écriture, et si vous le voulez seulement certains champs ;\n- public uniquement si vous le décidez, par exemple en publiant un paquet de domaine (la structure, jamais vos entrées) ou en ouvrant un formulaire de contribution.\n\nVotre profil est privé lui aussi. La mise en relation entre personnes est prévue mais pas encore disponible, et elle demandera toujours votre accord."), image: null),
    ],
  ),
  (
    id: "basics",
    icon: "folder",
    title: (en: "First steps: collections, data formats, entries", fr: "Premiers pas : collections, formats de données, entrées"),
    summary: (en: "The three words of Brainy and how to create your first collection.", fr: "Les trois mots de Brainy et la création de votre première collection."),
    sections: [
      (title: (en: "The three words", fr: "Les trois mots"), text: (en: "- **Collection**: a container, like a binder (Home, Work, Health). Renaming is free; deleting it also deletes its entries.\n- **Data format**: the template of a kind of card, with 1 to 30 fields and its own pastel color. A collection holds 1 to 24 data formats.\n- **Entry**: a card filled with the values of one data format. It takes the pastel color of its data format.", fr: "- **Collection** : un conteneur, comme un classeur (Maison, Travail, Santé). Vous pouvez la renommer ; la supprimer supprime aussi ses entrées.\n- **Format de données** : le modèle d’un type de fiche, avec 1 à 30 champs et sa propre couleur pastel. Une collection contient de 1 à 24 formats de données.\n- **Entrée** : une fiche remplie avec les valeurs d’un format de données. Elle prend la couleur pastel de son format."), image: null),
      (title: (en: "Create a collection", fr: "Créer une collection"), text: (en: "1. Click **New collection** at the bottom of the side bar.\n2. Choose a starting point: start from scratch or a ready template (tasks, calendar, expenses, links, book, sport, measurements, shop and stock…).\n3. Give it a name and confirm.\n\nTo design every field yourself, use **More actions → Create manually**. Templates are only a starting point: everything stays editable and the collection never gets a permanent type.", fr: "1. Cliquez sur **Nouvelle collection** en bas de la barre latérale.\n2. Choisissez un point de départ : partir de zéro ou un modèle prêt (tâches, agenda, dépenses, liens, livre, sport, mesures, commerce et stock…).\n3. Donnez-lui un nom et validez.\n\nPour concevoir chaque champ vous-même, passez par **Autres actions → Créer manuellement**. Un modèle n’est qu’un point de départ : tout reste modifiable et la collection n’a jamais de type permanent."), image: "templates"),
      (title: (en: "Find your way in a collection", fr: "Se repérer dans une collection"), text: (en: "The collection header shows the number of entries and data formats, with **New entry**, **Calculations** and **Manage** (rename, domain packages, delete). Below, three tabs:\n- **Entries**: the list, views, search and filters;\n- **Data formats**: the cards of your data formats, to add or edit fields;\n- **Tools**: advanced tools (stock, map, objects, classifications, states, sources, register, privacy).", fr: "L’en-tête de la collection indique le nombre d’entrées et de formats de données, avec **Nouvelle entrée**, **Calculs** et **Gérer** (renommer, paquets de domaine, supprimer). Dessous, trois onglets :\n- **Entrées** : la liste, les vues, la recherche et les filtres ;\n- **Formats de données** : les cartes de vos formats, pour ajouter ou modifier des champs ;\n- **Outils** : les outils avancés (stock, carte, objets, classifications, états, sources, registre, confidentialité)."), image: null),
      (title: (en: "Your profile and help", fr: "Votre profil et l’aide"), text: (en: "- Your **photo** (or initial) and name in the top bar open your profile: name, profession, current job, studies, interests and hobbies. Everything stays private and can be changed at any time; the photo is optional.\n- The **welcome guide** shown after your first sign-in comes back from **More actions → Getting started guide**.\n- This **Guide and training** is in **More actions** too, with a search box. Click a screenshot to enlarge it.", fr: "- Votre **photo** (ou votre initiale) et votre nom, dans la barre du haut, ouvrent votre profil : nom, profession, poste actuel, études, centres d’intérêt et loisirs. Tout reste privé et modifiable à tout moment ; la photo est facultative.\n- Le **guide de bienvenue** montré après votre première connexion se rouvre depuis **Autres actions → Guide de démarrage**.\n- Ce **Guide et formation** se trouve aussi dans **Autres actions**, avec une recherche. Cliquez sur une capture pour l’agrandir."), image: null),
    ],
  ),
  (
    id: "formats",
    icon: "shapes",
    title: (en: "Data formats and field types", fr: "Formats de données et types de champs"),
    summary: (en: "All field types, units, choices and the rules that protect saved data.", fr: "Tous les types de champs, les unités, les choix et les règles qui protègent les données enregistrées."),
    sections: [
      (title: (en: "Edit a data format", fr: "Modifier un format de données"), text: (en: "In the **Data formats** tab, each card shows its fields and number of entries. Use its menu to edit, change the color, duplicate or copy it to another collection. Field names are unique in a data format, without regard to case.\n\nA field that already holds values cannot be removed or change its type or unit, and its existing choices stay available. You can always rename, reorder and add fields.\n\nIn the editor:\n- **Maximum number of entries**: empty for no limit, 1 for a unique card (a cover, a preface), any number above; the card then shows “2 / 5 entries”.\n- **Required** on a field: an entry that leaves it empty is refused, and the form marks it with *.\n- **Show in the list** on up to three fields: their values appear on each entry row.", fr: "Dans l’onglet **Formats de données**, chaque carte montre ses champs et son nombre d’entrées. Son menu permet de la modifier, de changer sa couleur, de la dupliquer ou de la copier vers une autre collection. Les noms de champs sont uniques dans un format de données, sans tenir compte des majuscules.\n\nUn champ qui contient déjà des valeurs ne peut être ni supprimé ni changer de type ou d’unité, et ses choix existants restent disponibles. Vous pouvez toujours renommer, réordonner et ajouter des champs.\n\nDans l’éditeur :\n- **Nombre maximal d’entrées** : vide pour aucune limite, 1 pour une fiche unique (une couverture, une préface), tout nombre au-delà ; la carte affiche alors « 2 / 5 entrées ».\n- **Obligatoire** sur un champ : une entrée qui le laisse vide est refusée, et le formulaire le marque d’un *.\n- **Afficher dans la liste** sur trois champs au plus : leurs valeurs apparaissent sur chaque ligne d’entrée."), image: "formats"),
      (title: (en: "Field types", fr: "Types de champs"), text: (en: "- **Title, text, long text, single character, web link**.\n- **Number** without unit, with a suggested unit (kg, km, €, FCFA…) or your own unit; decimal comma is accepted.\n- **Date, time, date and time, duration**.\n- **Checkbox (yes/no)**: a real checkbox in every form.\n- **Single or multiple choice** from a list you define.\n- **Attachment**: up to 2 MiB per file and 8 MiB per entry, larger files by reference.\n- **Measure**: a value with unit, uncertainty, quality and instrument.\n- **Object reference, code (classification), position and zone (map)** for advanced uses.\n- **Collaborator**: one or more people chosen among the collection owner and the owner’s collaborators, for example “Done by” in a task. A person whose collaboration ends stays on the entries already saved.", fr: "- **Titre, texte, texte long, caractère unique, lien web**.\n- **Nombre** sans unité, avec une unité proposée (kg, km, €, FCFA…) ou votre propre unité ; la virgule décimale est acceptée.\n- **Date, heure, date et heure, durée**.\n- **Case à cocher (oui/non)** : une vraie case dans tous les formulaires.\n- **Choix unique ou multiple** dans une liste que vous définissez.\n- **Pièce jointe** : 2 Mio par fichier et 8 Mio par entrée, les fichiers plus lourds par référence.\n- **Mesure** : une valeur avec unité, incertitude, qualité et instrument.\n- **Référence d’objet, code (classification), position et zone (carte)** pour les usages avancés.\n- **Collaborateur** : une ou plusieurs personnes choisies parmi le propriétaire de la collection et ses collaborateurs, par exemple « Effectuée par » dans une tâche. Une personne dont la collaboration prend fin reste sur les entrées déjà enregistrées."), image: "format-editor"),
    ],
  ),
  (
    id: "entries",
    icon: "pencil",
    title: (en: "Entries: write, find, copy", fr: "Entrées : saisir, retrouver, copier"),
    summary: (en: "Create and edit entries, quick entry, quick capture, search and filters.", fr: "Créer et modifier des entrées, saisie rapide, capture rapide, recherche et filtres."),
    sections: [
      (title: (en: "Create and edit an entry", fr: "Créer et modifier une entrée"), text: (en: "1. Click **New entry** and choose the data format.\n2. Fill in at least one field and every field marked * (required); the others can stay empty.\n3. Save. The entry appears as one slim row with its pastel color, its title, up to three values, its creation date and, after a change, its modification date.\n\nFrom the row: a **double-click** (double-tap on a phone), the title or **Details** shows every value, the **⋯** menu lets you edit, copy as readable text, link to other entries, set a reminder or delete. The data format of an existing entry never changes.", fr: "1. Cliquez sur **Nouvelle entrée** et choisissez le format de données.\n2. Renseignez au moins un champ et chaque champ marqué * (obligatoire) ; les autres peuvent rester vides.\n3. Enregistrez. L’entrée apparaît en une ligne fine avec sa couleur pastel, son titre, jusqu’à trois valeurs, sa date de création et, après une modification, sa date de modification.\n\nDepuis la ligne : un **double-clic** (double-toucher sur téléphone), le titre ou **Détails** montre toutes les valeurs, le menu **⋯** permet de modifier, copier en texte lisible, relier à d’autres entrées, poser un rappel ou supprimer. Le format de données d’une entrée existante ne change jamais."), image: "entry-form"),
      (title: (en: "Go faster", fr: "Aller plus vite"), text: (en: "- **Quick entry** (Entries tab): a short form that remembers your usual values, the “today” dates and the fields you hide, and can duplicate the last entry.\n- **Capture** (top bar): keep a link, a text or a file in a few seconds, with a context note.\n- **Search** (press **/** to jump into it) and **filters** by data format and by field (equals, contains, greater than, less than); **Clear filters** brings everything back.\n- **Pages** for long lists: total, first and last page, a page number to type, **Go to date** and 30, 50 or 100 entries per page.", fr: "- **Saisie rapide** (onglet Entrées) : un formulaire court qui retient vos valeurs habituelles, les dates « du jour » et les champs masqués, et peut dupliquer la dernière entrée.\n- **Capturer** (barre du haut) : gardez un lien, un texte ou un fichier en quelques secondes, avec une note de contexte.\n- **Recherche** (touche **/** pour y aller) et **filtres** par format de données et par champ (égal, contient, supérieur, inférieur) ; **Effacer les filtres** remet tout.\n- **Pages** pour les longues listes : total, première et dernière page, numéro de page à taper, **Aller à la date** et 30, 50 ou 100 entrées par page."), image: "quick-entry"),
    ],
  ),
  (
    id: "views",
    icon: "layout",
    title: (en: "Views: list, table, cards, tasks, calendar", fr: "Vues : liste, tableau, fiches, tâches, agenda"),
    summary: (en: "Save the way you look at your entries and work in a spreadsheet.", fr: "Enregistrez votre façon de regarder vos entrées et travaillez comme dans un tableur."),
    sections: [
      (title: (en: "Saved views", fr: "Vues enregistrées"), text: (en: "A view keeps a layout, the data formats shown, columns, search, filter and order. Use **Save a view** in the Entries tab, then pick it in the **View** list. Layouts: list, table, cards, tasks (done checkbox, due date, priority) and calendar (start and end, time zone, recurrences).\n\nThe view you choose stays chosen: Brainy remembers it for each collection on your account, with the page size, so every device reopens on the same screen.\n\nThe **manual order** sorts entries by a number field, for example chapters of a book.", fr: "Une vue garde une présentation, les formats de données affichés, les colonnes, la recherche, le filtre et l’ordre. Utilisez **Enregistrer une vue** dans l’onglet Entrées, puis choisissez-la dans la liste **Vue**. Présentations : liste, tableau, fiches, tâches (case terminée, échéance, priorité) et agenda (début et fin, fuseau horaire, répétitions).\n\nLa vue choisie le reste : Brainy la retient pour chaque collection sur votre compte, avec la taille de page, et chaque appareil rouvre sur le même écran.\n\nL’**ordre saisi** trie les entrées selon un champ nombre, par exemple les chapitres d’un livre."), image: null),
      (title: (en: "Spreadsheet mode", fr: "Mode tableur"), text: (en: "In a table view, turn on **Spreadsheet mode** to edit cells directly: arrows, Enter or F2 to edit, Tab, Esc, Delete. Add a row or a column; a number column asks for its unit (or “No unit”). An invalid value stays shown with the reason. Complex types open the full form.\n\nClick a column title to sort (again for the reverse order, a third time to undo). Drag the edge of a title to widen a column, or use the left and right arrows on it; double-click restores the width. **Shift + arrows** or **Shift + click** select several cells (long press on a touch screen); **Ctrl+C** and **Ctrl+V** copy and paste with Excel, Sheets or LibreOffice, and pasted lines below the table become new rows; **Ctrl+D** copies the first selected row into the rows below.", fr: "Dans une vue tableau, activez le **mode tableur** pour modifier les cellules directement : flèches, Entrée ou F2 pour modifier, Tab, Échap, Suppr. Ajoutez une ligne ou une colonne ; une colonne nombre demande son unité (ou « Sans unité »). Une valeur invalide reste affichée avec la raison. Les types complexes ouvrent le formulaire complet.\n\nCliquez sur le titre d’une colonne pour trier (encore une fois pour l’ordre inverse, une troisième pour annuler). Faites glisser le bord d’un titre pour élargir une colonne, ou utilisez les flèches gauche et droite dessus ; un double clic rend la largeur d’origine. **Maj + flèches** ou **Maj + clic** sélectionnent plusieurs cellules (appui long sur un écran tactile) ; **Ctrl+C** et **Ctrl+V** copient et collent avec Excel, Sheets ou LibreOffice, et les lignes collées sous le tableau deviennent de nouvelles lignes ; **Ctrl+D** recopie la première ligne sélectionnée dans les lignes en dessous."), image: "table"),
    ],
  ),
  (
    id: "templates",
    icon: "template",
    title: (en: "Templates for everyday life", fr: "Les modèles du quotidien"),
    summary: (en: "Task planner, saved links with previews, book view, expenses and more.", fr: "Planning des tâches, liens avec aperçu, vue livre, dépenses et plus."),
    sections: [
      (title: (en: "Task list: day and calendar", fr: "Liste de tâches : jour et calendrier"), text: (en: "Each task is either done **once** over a period or **repeats**: every day, every N days, some weekdays, every week or every month. The form only shows the fields that matter for your choice.\n\n- **Tasks by day**: overdue, to do and done, with a progress bar. A repeating task is checked day by day and a missed day stays missed.\n- **Task calendar**: the month with a done/total counter per day; click a day to see and check its tasks.\n- A reminder set on the **Start** of a repeating task comes back at each open occurrence.", fr: "Chaque tâche est faite **une seule fois** sur une période ou **revient** : chaque jour, tous les N jours, certains jours de la semaine, chaque semaine ou chaque mois. Le formulaire n’affiche que les champs utiles à votre choix.\n\n- **Tâches du jour** : en retard, à faire et faites, avec une barre de progression. Une tâche qui revient se coche jour par jour et un jour oublié reste manqué.\n- **Calendrier des tâches** : le mois avec un compteur faites/total par jour ; cliquez sur un jour pour voir et cocher ses tâches.\n- Un rappel posé sur le **Début** d’une tâche qui revient se reprogramme à chaque occurrence non cochée."), image: "tasks-day"),
      (title: (en: "Calendar of the month", fr: "Le calendrier du mois"), text: (en: "The calendar shows at a glance which days are complete (green), late (red) or still open. On a phone, each day shows its counter only.", fr: "Le calendrier montre d’un coup d’œil les jours terminés (vert), en retard (rouge) ou encore ouverts. Sur téléphone, chaque jour n’affiche que son compteur."), image: "tasks-calendar"),
      (title: (en: "Saved links with previews", fr: "Liens conservés avec aperçu"), text: (en: "In a Saved links collection, a link field holding a web address shows a preview: in the list, one slim line with a small image, the page title and the site (with a play mark for videos); click it to open the link. Brainy fetches the preview safely and copies the image, so the site never sees your device.", fr: "Dans une collection Liens conservés, un champ lien qui contient une adresse web affiche un aperçu : dans la liste, une ligne fine avec une petite image, le titre de la page et le site (avec un signe lecture pour les vidéos) ; cliquez-le pour ouvrir le lien. Brainy récupère l’aperçu de façon sûre et recopie l’image : le site ne voit jamais votre appareil."), image: "links"),
      (title: (en: "Book: write and lay out", fr: "Livre : écrire et mettre en page"), text: (en: "The Book template creates the parts of a book: cover, front matter, parts, chapters, sections, appendices, terms and sources. Single pages (preface, dedication…) accept one entry; a chapter can only go under a part.\n\nThe **book view** shows real pages: click a text to edit it with **bold**, *italic*, subheadings and quotes, change fonts, sizes, spacing and margins with the ruler, then **Print or PDF** on the web.\n\n**Pages** shows the book cut into real pages with their numbers; the contents and the index then give page numbers. **Save as PDF** (mobile and desktop) or **Print or PDF** (web) produces the file. Under **Data formats in the book**, the owner chooses how any other data format appears: part, chapter, section, appendix, term or source. In a shared collection, each part shows who wrote it and who changed it last.", fr: "Le modèle Livre crée les parties d’un livre : couverture, pages liminaires, parties, chapitres, sections, annexes, termes et sources. Les pages uniques (préface, dédicace…) n’acceptent qu’une entrée ; un chapitre ne se place que sous une partie.\n\nLa **vue livre** montre de vraies pages : cliquez sur un texte pour le modifier avec **gras**, *italique*, intertitres et citations, réglez polices, tailles, espacements et marges avec la règle, puis **Imprimer ou PDF** sur le web.\n\n**Pages** montre le livre découpé en vraies pages numérotées ; la table des matières et l’index donnent alors les numéros de page. **Enregistrer en PDF** (mobile et ordinateur) ou **Imprimer ou PDF** (web) produit le fichier. Sous **Formats de données dans le livre**, le propriétaire choisit comment tout autre format de données apparaît : partie, chapitre, section, annexe, terme ou source. Dans une collection partagée, chaque partie montre qui l’a écrite et qui l’a modifiée en dernier."), image: "book"),
      (title: (en: "Other templates", fr: "Autres modèles"), text: (en: "- **Expenses** and **KT personal**: amounts with week, month and year totals.\n- **Calendar**: events with start, end and place.\n- **Fitness**: exercises, workouts, sets and a training calendar.\n- **Measurements** (science, weather, health, machines): dated values with quality and source.\n- **Shop and stock**: products, suppliers and confirmed stock movements.", fr: "- **Dépenses** et **KT personal** : des montants avec totaux de la semaine, du mois et de l’année.\n- **Agenda** : rendez-vous avec début, fin et lieu.\n- **Entraînement et sport** : exercices, séances, séries et calendrier d’entraînement.\n- **Mesures** (science, météo, santé, machines) : valeurs datées avec qualité et source.\n- **Commerce et stock** : produits, fournisseurs et mouvements de stock validés."), image: null),
    ],
  ),
  (
    id: "analysis",
    icon: "chart",
    title: (en: "Calculations, statistics and charts", fr: "Calculs, statistiques et graphiques"),
    summary: (en: "Formulas, analyses, charts and forecasts: the first step toward studying your data.", fr: "Formules, analyses, graphiques et prévisions : le premier pas vers l’étude de vos données."),
    sections: [
      (title: (en: "Analyze a field", fr: "Analyser un champ"), text: (en: "Open **Calculations** in the collection header. Choose a data format, a field and an operation: count, sum, average, minimum, maximum, median, percentiles, rates, weighted averages, moving windows… Group by day, month, category, object or zone, compare two periods and filter.\n\nResults keep their units and are shown as a key figure or a chart: bars, lines, several series, stacked areas, gauge, scatter plot or radar, with zoom and export.\n\nWith a collaborator field, **Person** groups the results by person: an entry counts for each person it names.", fr: "Ouvrez **Calculs** dans l’en-tête de la collection. Choisissez un format de données, un champ et une opération : nombre, somme, moyenne, minimum, maximum, médiane, percentiles, taux, moyennes pondérées, fenêtres glissantes… Regroupez par jour, mois, catégorie, objet ou zone, comparez deux périodes et filtrez.\n\nLes résultats gardent leurs unités et s’affichent en chiffre clé ou en graphique : barres, courbes, plusieurs séries, aires empilées, jauge, nuage de points ou radar, avec zoom et export.\n\nAvec un champ collaborateur, **Personne** regroupe les résultats par personne : une entrée compte pour chaque personne qu’elle nomme."), image: "insights"),
      (title: (en: "Formulas and forecasts", fr: "Formules et prévisions"), text: (en: "- **Formulas** compute a value for each entry from its fields and the properties of referenced objects (with units, dates, text and conditions); cycles and divisions by zero are refused.\n- **Forecasts** (average or linear trend) are explainable, can leave out a period and always stay separate from real observations.\n- **Sensitivity limits** hide groups that are too small when you analyze personal data.", fr: "- Les **formules** calculent une valeur pour chaque entrée à partir de ses champs et des propriétés des objets référencés (avec unités, dates, texte et conditions) ; les cycles et divisions par zéro sont refusés.\n- Les **prévisions** (moyenne ou tendance linéaire) sont explicables, peuvent écarter une période et restent toujours séparées des observations réelles.\n- Les **seuils de sensibilité** masquent les groupes trop petits quand vous analysez des données personnelles."), image: null),
    ],
  ),
  (
    id: "objects",
    icon: "boxes",
    title: (en: "Objects, relations and links", fr: "Objets, relations et liens"),
    summary: (en: "Named things with history, references, parent-child relations and links between entries.", fr: "Des choses nommées avec historique, des références, des relations parent-enfant et des liens entre entrées."),
    sections: [
      (title: (en: "Objects and references", fr: "Objets et références"), text: (en: "Mark a data format as an **object model** (Tools → Objects) to give its entries a stable identity, properties, duplication and history: a product, a machine, a patient, a plot of land. Another data format can then reference one or several objects, either following their current value or keeping a snapshot. **Use in an entry** creates a frozen summary linked to its source.\n\nLocal **units** (Tools → Measures and conversions) and exchange rates let you convert quantities.", fr: "Marquez un format de données comme **modèle d’objets** (Outils → Objets) pour donner à ses entrées une identité stable, des propriétés, une duplication et un historique : un produit, une machine, un patient, une parcelle. Un autre format peut alors référencer un ou plusieurs objets, en suivant leur valeur actuelle ou en gardant un instantané. **Utiliser dans une entrée** crée un résumé figé relié à sa source.\n\nLes **unités** locales (Outils → Mesures et conversions) et les taux de change permettent de convertir des quantités."), image: "tools"),
      (title: (en: "Relations and links", fr: "Relations et liens"), text: (en: "- **Parent-child** relations build hierarchies (country › region › city) and totals along them; a cycle is refused.\n- **Composition** with quantity and unit models recipes and bills of materials.\n- **Links between entries** connect two cards with a label; a duplicate web link is detected.", fr: "- Les relations **parent-enfant** construisent des hiérarchies (pays › région › ville) et des totaux le long de celles-ci ; un cycle est refusé.\n- La **composition** avec quantité et unité décrit recettes et nomenclatures.\n- Les **liens entre entrées** relient deux fiches avec un libellé ; un lien web en double est détecté."), image: null),
    ],
  ),
  (
    id: "operations",
    icon: "warehouse",
    title: (en: "Stock, map, classifications and states", fr: "Stock, carte, classifications et états"),
    summary: (en: "Operational tools for shops, field work and processes.", fr: "Des outils opérationnels pour le commerce, le terrain et les processus."),
    sections: [
      (title: (en: "Stock", fr: "Stock"), text: (en: "Stock rules turn entries into explicit movements: receipt, sale or outgoing, transfer between places and correction. Every movement is previewed before you confirm it, and the current stock is always derived from movements, never typed by hand.", fr: "Les règles de stock transforment des entrées en mouvements explicites : réception, vente ou sortie, transfert entre lieux et correction. Chaque mouvement est prévisualisé avant validation, et le stock courant est toujours calculé à partir des mouvements, jamais saisi à la main."), image: null),
      (title: (en: "Map, classifications, states", fr: "Carte, classifications, états"), text: (en: "- **Map**: position and zone fields, distances and totals per zone, GeoJSON and CSV import and export.\n- **Classifications**: your own code lists or imported references (hierarchical, mergeable, copyable).\n- **States and approvals**: a workflow of states with transitions per role, required fields, assignees and due dates.", fr: "- **Carte** : champs position et zone, distances et totaux par zone, import et export GeoJSON et CSV.\n- **Classifications** : vos propres listes de codes ou des référentiels importés (hiérarchiques, fusionnables, copiables).\n- **États et validations** : un flux d’états avec transitions par rôle, champs obligatoires, personnes assignées et échéances."), image: null),
    ],
  ),
  (
    id: "sharing",
    icon: "users",
    title: (en: "Collaborators and sharing", fr: "Collaborateurs et partage"),
    summary: (en: "Become collaborators with a link, share a collection in read only or read and write, and see who wrote what.", fr: "Devenir collaborateurs par un lien, partager une collection en lecture seule ou en lecture et écriture, et voir qui a écrit quoi."),
    sections: [
      (title: (en: "Become collaborators", fr: "Devenir collaborateurs"), text: (en: "You can only share with a **collaborator**. Open **More actions → Collaborators**: you have a personal link to send by WhatsApp, Facebook, e-mail… The person who opens it signs in or creates an account, then clicks **Accept the collaboration**.\n\nBeing collaborators gives access to **nothing** yet: each of you then decides, collection by collection, what to share.\n- **Create a new link** cancels the old one; your current collaborators stay.\n- In the mobile and desktop app, paste a link you received in **Accept a link you received**.\n- **End collaboration** removes every share between you two, in both directions.", fr: "Vous ne pouvez partager qu’avec un **collaborateur**. Ouvrez **Autres actions → Collaborateurs** : vous y trouvez votre lien personnel à envoyer par WhatsApp, Facebook, e-mail… La personne qui l’ouvre se connecte ou crée un compte, puis clique sur **Accepter la collaboration**.\n\nÊtre collaborateurs ne donne encore accès à **rien** : chacun décide ensuite, collection par collection, ce qu’il partage.\n- **Créer un nouveau lien** annule l’ancien ; vos collaborateurs actuels restent.\n- Dans l’application mobile et ordinateur, collez un lien reçu dans **Accepter un lien reçu**.\n- **Mettre fin à la collaboration** retire tous les partages entre vous deux, dans les deux sens."), image: "collaborators"),
      (title: (en: "Share a collection", fr: "Partager une collection"), text: (en: "1. Open your collection and click **Share** in its header (only the owner sees it).\n2. For each collaborator, choose **Read only** or **Read and write**, or leave **No access**.\n3. The change applies at once; choose **No access** to remove the access.\n\nThe collection then appears for that person in the **Shared** tab at the top of the collection list, with your name. **Mine** brings back their own collections; each tab shows how many collections it holds.\n\nWith many collaborators, type part of a name or an e-mail in the search box: the list narrows as you type. The same search exists in **More actions → Collaborators**.", fr: "1. Ouvrez votre collection et cliquez sur **Partager** dans son en-tête (seul le propriétaire le voit).\n2. Pour chaque collaborateur, choisissez **Lecture seule** ou **Lecture et écriture**, ou laissez **Aucun accès**.\n3. Le changement s’applique aussitôt ; choisissez **Aucun accès** pour retirer l’accès.\n\nLa collection apparaît alors chez cette personne dans l’onglet **Partagées**, en haut de la liste des collections, avec votre nom. **À moi** ramène ses propres collections ; chaque onglet indique combien de collections il contient.\n\nAvec beaucoup de collaborateurs, tapez une partie d’un nom ou d’une adresse e-mail dans le champ de recherche : la liste se réduit pendant la saisie. La même recherche existe dans **Autres actions → Collaborateurs**."), image: "share"),
      (title: (en: "Work in a shared collection", fr: "Travailler dans une collection partagée"), text: (en: "A banner recalls who shared the collection and your access.\n- **Read only**: you see, search, filter and copy the entries; nothing can be changed.\n- **Read and write**: you also create, edit and delete **entries**.\n- The structure stays with the owner: the **Data formats** tab, renaming, deleting and sharing are not shown to collaborators.\n\nEach entry shows at the top left the photo and name of the person who **created** it and, after a change, of the **last** person who edited it (not in the spreadsheet view).\n- With read and write access, you can also set **your own reminders** on an entry; only you receive them.\n- **Saved views** are managed by the owner: everyone can choose and use them.", fr: "Un bandeau rappelle qui a partagé la collection et votre accès.\n- **Lecture seule** : vous voyez, recherchez, filtrez et copiez les entrées ; rien ne peut être modifié.\n- **Lecture et écriture** : vous créez aussi, modifiez et supprimez les **entrées**.\n- La structure reste au propriétaire : l’onglet **Formats de données**, le renommage, la suppression et le partage ne sont pas proposés aux collaborateurs.\n\nChaque entrée montre en haut à gauche la photo et le nom de la personne qui l’a **créée** et, après une modification, de la **dernière** personne qui l’a modifiée (sauf en vue tableur).\n- En lecture et écriture, vous pouvez aussi poser **vos propres rappels** sur une entrée ; vous seul les recevez.\n- Les **vues enregistrées** sont gérées par le propriétaire : chacun peut les choisir et les utiliser."), image: "shared-collection"),
      (title: (en: "Fields that stay private", fr: "Des champs qui restent privés"), text: (en: "In **Tools → Privacy**, the owner marks data formats and fields as personal or sensitive and chooses which fields each collaborator may see. Sensitive fields stay hidden from a share unless you allow them, and every important action is written in the audit log.", fr: "Dans **Outils → Confidentialité**, le propriétaire marque des formats de données et des champs comme personnels ou sensibles et choisit les champs que chaque collaborateur peut voir. Les champs sensibles restent masqués dans un partage sauf si vous les autorisez, et chaque action importante est inscrite au journal d’audit."), image: "privacy"),
      (title: (en: "Collect, copy, publish", fr: "Collecter, copier, publier"), text: (en: "- **Public contributions**: a form link for people without an account; answers wait in quarantine until you accept them.\n- **Copy, move or link** a data format or an object to another collection, always with a preview and an explicit target.\n- **Domain packages** share a structure (data formats, units, lists) without any entry, with an optional signature.\n- **Import and export** (More actions) in CSV or Brainy files, and full **backups** (Workspace tools).", fr: "- **Contributions publiques** : un lien de formulaire pour des personnes sans compte ; les réponses attendent en quarantaine que vous les acceptiez.\n- **Copier, déplacer ou lier** un format de données ou un objet vers une autre collection, toujours avec un aperçu et une cible explicite.\n- Les **paquets de domaine** partagent une structure (formats, unités, listes) sans aucune entrée, avec une signature facultative.\n- **Importer et exporter** (Autres actions) en CSV ou fichier Brainy, et **sauvegardes** complètes (Outils de l’espace)."), image: null),
    ],
  ),
  (
    id: "trust",
    icon: "shield",
    title: (en: "Trust: sensitivity, register, audit", fr: "Confiance : sensibilité, registre, audit"),
    summary: (en: "Tools for data that must stay exact and protected.", fr: "Des outils pour les données qui doivent rester exactes et protégées."),
    sections: [
      (title: (en: "Protect and prove", fr: "Protéger et prouver"), text: (en: "- **Sensitivity levels** (ordinary, personal, sensitive) per data format and field: shares hide sensitive fields and exports leave them out unless you choose otherwise.\n- The **register** makes a data format append-only: writings are chained, cannot be edited or deleted, and are corrected by a linked counter-writing. You can verify integrity and export a proof.\n- The **audit log** lists who did what and when.", fr: "- Les **niveaux de sensibilité** (ordinaire, personnel, sensible) par format de données et par champ : les partages masquent les champs sensibles et les exports les excluent sauf choix contraire.\n- Le **registre** rend un format de données non modifiable : les écritures sont chaînées, ne se modifient ni ne se suppriment, et se corrigent par une contre-écriture liée. Vous pouvez vérifier l’intégrité et exporter une preuve.\n- Le **journal d’audit** indique qui a fait quoi et quand."), image: null),
    ],
  ),
  (
    id: "scale",
    icon: "database",
    title: (en: "Toward large data", fr: "Vers les grandes données"),
    summary: (en: "Large files, background processing and outside sources: Brainy’s big data foundations.", fr: "Fichiers lourds, traitements en arrière-plan et sources externes : les fondations big data de Brainy."),
    sections: [
      (title: (en: "Built to grow", fr: "Conçu pour grandir"), text: (en: "- **Large files** above 2 MiB are uploaded in parts with resume and stored by reference with a checksum; Brainy catalogs them without analyzing them.\n- **Background processing** imports, exports and recalculates large volumes while you keep working.\n- **Data sources** connect files and outside systems; incoming rows are checked against your data formats before they become entries.\n- **Offline**: entries saved without network wait on the device and are sent later.\n\nThese foundations are what will let Brainy serve studies on very large data sets. Some modules may be paused on a given hosting plan; Brainy says so when it happens.", fr: "- Les **fichiers lourds** de plus de 2 Mio sont envoyés par morceaux avec reprise et conservés par référence avec une empreinte ; Brainy les catalogue sans les analyser.\n- Les **traitements en arrière-plan** importent, exportent et recalculent de grands volumes pendant que vous continuez à travailler.\n- Les **sources de données** relient des fichiers et des systèmes externes ; les lignes reçues sont vérifiées par vos formats de données avant de devenir des entrées.\n- **Hors ligne** : les entrées enregistrées sans réseau attendent sur l’appareil et partent plus tard.\n\nCes fondations permettront à Brainy de servir des études sur de très grands volumes. Certains modules peuvent être en pause sur un hébergement donné ; Brainy l’indique alors."), image: null),
    ],
  ),
];
